input.command:
cat > /tmp/scan.pl <<'EOF'
use strict; use warnings;
use Compress::Raw::Zlib qw(crc32);
my $T = 0x62D5D25F;
open(my $fh, '<:raw', '/app/john/run/password.lst') or die $!;
while (my $line = <$fh>) {
  $line =~ s/\r?\n\z//;
  my @c;
  push @c, $line if length($line)==9;
  push @c, $line."\n" if length($line)==8;
  push @c, $line."\r\n" if length($line)==7;
  for my $c (@c) {
    if ((crc32($c) & 0xffffffff) == $T) { print "FOUND: ", unpack("H*",$c), " = [$c]\n"; }
  }
  my $l = lc $line;
  if ($l ne $line) {
    @c=();
    push @c, $l if length($l)==9;
    push @c, $l."\n" if length($l)==8;
    push @c, $l."\r\n" if length($l)==7;
    for my $c (@c) { if ((crc32($c)&0xffffffff)==$T) { print "FOUNDLC: ",unpack("H*",$c)," = [$c]\n"; } }
  }
}
print "done\n";
EOF
perl /tmp/scan.pl
